import type { Hook, Register } from 'claude-code'

type Ttl = '5m' | '1h'
type Api = Parameters<Hook<'session.start'>>[0]

const LABELS: Record<Ttl, string> = { '1h': '1 hour', '5m': '5 minutes' }

function parseTtl(text: string): Ttl | undefined {
  const t = text.trim().toLowerCase()
  if (t === '1h' || t === LABELS['1h']) return '1h'
  if (t === '5m' || t === LABELS['5m'].toLowerCase()) return '5m'
  return undefined
}

async function current($: Api): Promise<Ttl> {
  const env = await $.env.get('CLAUDE_CODE_PROMPT_CACHE_TTL')
  const settings = ((await $.settings.read().catch(() => ({}))) ?? {}) as Record<string, unknown>
  return (env ?? settings.promptCacheTtl) === '1h' ? '1h' : '5m'
}

async function apply($: Api, ttl: Ttl): Promise<void> {
  await $.env.set('CLAUDE_CODE_PROMPT_CACHE_TTL', ttl)
  $.ui.status(`TTL ${ttl}`)
}

async function askTtl($: Api): Promise<void> {
  const def = await current($)
  const options = def === '1h' ? [LABELS['1h'], LABELS['5m']] : [LABELS['5m'], LABELS['1h']]
  const answer = await $.ui.ask('Prompt-cache TTL for this session?', { header: 'Cache TTL', options })
  const ttl = parseTtl(answer)
  if (ttl) await apply($, ttl)
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const result = await next(e)
    await $.command.register({ name: 'ttl', description: 'Prompt-cache TTL for this session: /ttl 5m|1h' })
    // Not awaited, so the session start never waits on the dialog.
    if (e.isInteractive) void askTtl($).catch(() => {})
    return result
  })

  on('command.run', { command: 'ttl' }, async ($, e) => {
    const ttl = parseTtl(e.args)
    if (!ttl) return { text: `Prompt-cache TTL: ${await current($)} (use /ttl 5m or /ttl 1h)` }
    await apply($, ttl)
    return { text: `Prompt-cache TTL: ${ttl}` }
  })
}

